message.content:
{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2156-09-11 22:30:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I’ll be taking care of you tonight. Can you tell me what brought you to the hospital?"
    },
    {
      "turn_number": 2,
      "time": "2156-09-11 22:31:00",
      "speaker": "Patient",
      "text": "Hi. My stomach pain got way worse over the weekend. It’s in my upper belly and now it’s going to my right side. I couldn’t keep anything down."
    },
    {
      "turn_number": 3,
      "time": "2156-09-11 22:32:00",
      "speaker": "Doctor",
      "text": "I see. And you said you vomited? What did it look like?"
    },
    {
      "turn_number": 4,
      "time": "2156-09-11 22:33:00",
      "speaker": "Patient",
      "text": "Yeah, three times last night. First like food, then yellow. No blood. I’ve also had diarrhea—five times today."
    },
    {
      "turn_number": 5,
      "time": "2156-09-11 22:34:00",
      "speaker": "Doctor",
      "text": "Okay. Any fever or chills?"
    },
    {
      "turn_number": 6,
      "time": "2156-09-11 22:35:00",
      "speaker": "Patient",
      "text": "Chills, but no fever. I took juice this morning and it made the pain so bad I had to come in."
    },
    {
      "turn_number": 7,
      "time": "2156-09-11 22:36:00",
      "speaker": "Doctor",
      "text": "I understand. We’ve started IV fluids and gave you some Dilaudid in the ER. How’s the pain now?"
    },
    {
      "turn_number": 8,
      "time": "2156-09-11 22:37:00",
      "speaker": "Patient",
      "text": "A little better, but still really bad. I take 6 mg Dilaudid every 4 hours at home, but it’s not helping."
    },
    {
      "turn_number": 9,
      "time": "2156-09-11 22:38:00",
      "speaker": "Doctor",
      "text": "We’re giving you 0.25 mg IV Dilaudid every 3 hours as needed. That’s the same dose you had last time and we’ll stick with it for safety."
    },
    {
      "turn_number": 10,
      "time": "2156-09-11 22:39:00",
      "speaker": "Patient",
      "text": "But it’s not enough. I need more."
    },
    {
      "turn_number": 11,
      "time": "2156-09-11 22:40:00",
      "speaker": "Doctor",
      "text": "I hear you’re in pain, but we need to balance relief with safety. We’ll keep monitoring and adjusting as needed."
    },
    {
      "turn_number": 12,
      "time": "2156-09-11 22:41:00",
      "speaker": "Patient",
      "text": "Fine. But I also haven’t had a real bowel movement in days. I’ve tried everything."
    },
    {
      "turn_number": 13,
      "time": "2156-09-11 22:42:00",
      "speaker": "Doctor",
      "text": "Your labs show a high white count and mild dehydration. We did an X-ray with contrast through your GJ tube."
    },
    {
      "turn_number": 14,
      "time": "2156-09-11 22:43:00",
      "speaker": "Patient",
      "text": "And? Is the tube okay?"
    },
    {
      "turn_number": 15,
      "time": "2156-09-11 22:44:00",
      "speaker": "Doctor",
      "text": "Yes, the tube is in the right place—no blockage or leak. The ultrasound also showed no abscess around the site, just some redness."
    },
    {
      "turn_number": 16,
      "time": "2156-09-11 22:45:00",
      "speaker": "Patient",
      "text": "I’ve been on antibiotics since the ER. Do I need them?"
    },
    {
      "turn_number": 17,
      "time": "2156-09-11 22:46:00",
      "speaker": "Doctor",
      "text": "We started vancomycin because of the redness, but since there’s no infection sign, we’ll stop after three days. Your primary doctor will check the site next week."
    },
    {
      "turn_number": 18,
      "time": "2156-09-11 22:47:00",
      "speaker": "Patient",
      "text": "Okay. But I’m really worried about the constipation. I can’t keep going like this."
    },
    {
      "turn_number": 19,
      "time": "2156-09-11 22:48:00",
      "speaker": "Doctor",
      "text": "We’re adding oral naloxone to help with opioid-related constipation. It can help you pass stool without affecting pain control."
    },
    {
      "turn_number": 20,
      "time": "2156-09-12 08:15:00",
      "speaker": "Doctor",
      "text": "Good morning. I heard you had a bowel movement last night?"
    },
    {
      "turn_number": 21,
      "time": "2156-09-12 08:16:00",
      "speaker": "Patient",
      "text": "Yes! A big one. I feel so much better. Still some pain, but not as bad."
    },
    {
      "turn_number": 22,
      "time": "2156-09-12 08:17:00",
      "speaker": "Doctor",
      "text": "That’s great. We’ll keep you on the new bowel regimen—Colace, senna, and lactulose—to prevent this again."
    },
    {
      "turn_number": 23,
      "time": "2156-09-12 08:18:00",
      "speaker": "Patient",
      "text": "Can I start drinking again? I’m so thirsty."
    },
    {
      "turn_number": 24,
      "time": "2156-09-12 08:19:00",
      "speaker": "Doctor",
      "text": "You tolerated clear liquids overnight. We’ll keep advancing your diet slowly—start with broth and jello today."
    },
    {
      "turn_number": 25,
      "time": "2156-09-12 08:20:00",
      "speaker": "Patient",
      "text": "And my diabetes? My sugar was low this morning."
    },
    {
      "turn_number": 26,
      "time": "2156-09-12 08:21:00",
      "speaker": "Doctor",
      "text": "We’re continuing your NPH insulin and using Humalog as needed. We’ll make sure your levels stay stable before discharge."
    },
    {
      "turn_number": 27,
      "time": "2156-09-12 12:05:00",
      "speaker": "Doctor",
      "text": "I see you’re getting tube feeds now. How are you feeling with them?"
    },
    {
      "turn_number": 28,
      "time": "2156-09-12 12:06:00",
      "speaker": "Patient",
      "text": "Okay so far. No nausea. But I took some extra pills from my bag earlier."
    },
    {
      "turn_number": 29,
      "time": "2156-09-12 12:07:00",
      "speaker": "Doctor",
      "text": "We noticed that. For safety, we need to store your pills during your stay. They’ll be returned when you leave."
    },
    {
      "turn_number": 30,
      "time": "2156-09-12 12:08:00",
      "speaker": "Patient",
      "text": "No! That’s not fair! I need them!"
    },
    {
      "turn_number": 31,
      "time": "2156-09-12 12:09:00",
      "speaker": "Doctor",
      "text": "I understand you’re upset, but we have to follow safety rules. Security will help keep things calm."
    },
    {
      "turn_number": 32,
      "time": "2156-09-12 12:10:00",
      "speaker": "Patient",
      "text": "I’m leaving then!"
    },
    {
      "turn_number": 33,
      "time": "2156-09-12 12:11:00",
      "speaker": "Doctor",
      "text": "Code Purple has been called. You’ll get some Ativan and Zyprexa to help you calm down. This is for your safety."
    },
    {
      "turn_number": 34,
      "time": "2156-09-12 14:00:00",
      "speaker": "Doctor",
      "text": "How are you feeling now?"
    },
    {
      "turn_number": 35,
      "time": "2156-09-12 14:01:00",
      "speaker": "Patient",
      "text": "Better. Sorry about earlier. I was just scared."
    },
    {
      "turn_number": 36,
      "time": "2156-09-12 14:02:00",
      "speaker": "Doctor",
      "text": "It’s okay. We’re here to help. We had a talk with your primary doctor. Your pain plan won’t be increased, even at home."
    },
    {
      "turn_number": 37,
      "time": "2156-09-12 14:03:00",
      "speaker": "Patient",
      "text": "I don’t like it, but I understand."
    },
    {
      "turn_number": 38,
      "time": "2156-09-13 09:00:00",
      "speaker": "Doctor",
      "text": "You’ve done well. You’re off IV meds, eating clears, and had a good bowel movement. We’re planning to discharge you today."
    },
    {
      "turn_number": 39,
      "time": "2156-09-13 09:01:00",
      "speaker": "Patient",
      "text": "Really? That’s great. What about my meds?"
    },
    {
      "turn_number": 40,
      "time": "2156-09-13 09:02:00",
      "speaker": "Doctor",
      "text": "You’ll go home with scripts for the new bowel regimen. Keep using your regular insulin, GJ tube meds, and pain meds as prescribed."
    },
    {
      "turn_number": 41,
      "time": "2156-09-13 09:03:00",
      "speaker": "Patient",
      "text": "And the tube site?"
    },
    {
      "turn_number": 42,
      "time": "2156-09-13 09:04:00",
      "speaker": "Doctor",
      "text": "No antibiotics needed. Keep it clean. See your doctor in a week to check it."
    },
    {
      "turn_number": 43,
      "time": "2156-09-13 09:05:00",
      "speaker": "Patient",
      "text": "And if the pain comes back?"
    },
    {
      "turn_number": 44,
      "time": "2156-09-13 09:06:00",
      "speaker": "Doctor",
      "text": "Use your current pain meds as directed. If it’s unmanageable, come back. But no increases without discussing with your provider."
    },
    {
      "turn_number": 45,
      "time": "2156-09-13 09:07:00",
      "speaker": "Patient",
      "text": "Okay. Thank you."
    },
    {
      "turn_number": 46,
      "time": "2156-09-13 09:08:00",
      "speaker": "Doctor",
      "text": "You’re welcome. We’ll have your pills returned and get the discharge papers ready. You should be home by noon."
    },
    {
      "turn_number": 47,
      "time": "2156-09-13 10:30:00",
      "speaker": "Doctor",
      "text": "Just a quick check before you go. Any chest pain lately?"
    },
    {
      "turn_number": 48,
      "time": "2156-09-13 10:31:00",
      "speaker": "Patient",
      "text": "Just the usual—comes and goes, but not bad."
    },
    {
      "turn_number": 49,
      "time": "2156-09-13 10:32:00",
      "speaker": "Doctor",
      "text": "And it’s reproducible when I press here?"
    },
    {
      "turn_number": 50,
      "time": "2156-09-13 10:33:00",
      "speaker": "Patient",
      "text": "Yes, exactly. It’s probably just muscle."
    },
    {
      "turn_number": 51,
      "time": "2156-09-13 10:34:00",
      "speaker": "Doctor",
      "text": "Likely so. But mention it at your next visit. Otherwise, you’re cleared to go home."
    },
    {
      "turn_number": 52,
      "time": "2156-09-13 10:35:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor. I feel much better."
    },
    {
      "turn_number": 53,
      "time": "2156-09-13 10:36:00",
      "speaker": "Doctor",
      "text": "Take care. Follow up with your team and call if anything changes."
    },
    {
      "turn_number": 54,
      "time": "2156-09-13 10:37:00",
      "speaker": "Patient",
      "text": "I will. Have a good day."
    },
    {
      "turn_number": 55,
      "time": "2156-09-13 10:38:00",
      "speaker": "Doctor",
      "text": "You too. See you soon, hopefully not in the hospital!"
    },
    {
      "turn_number": 56,
      "time": "2156-09-13 10:39:00",
      "speaker": "Patient",
      "text": "Fingers crossed!"
    },
    {
      "turn_number": 57,
      "time": "2156-09-13 10:40:00",
      "speaker": "Doctor",
      "text": "Nurse will bring your discharge instructions and meds. You’re all set."
    },
    {
      "turn_number": 58,
      "time": "2156-09-13 10:41:00",
      "speaker": "Patient",
      "text": "Great. Thanks again."
    },
    {
      "turn_number": 59,
      "time": "2156-09-13 10:42:00",
      "speaker": "Doctor",
      "text": "Take care of yourself. We’re here if you need us."
    },
    {
      "turn_number": 60,
      "time": "2156-09-13 10:43:00",
      "speaker": "Patient",
      "text": "I will. Bye!"
    }
  ],
  "summary": {
    "admission_start": "2156-09-11 22:28:00",
    "admission_end": "2156-09-13 18:15:00",
    "summary_paragraph": "The patient was admitted for worsening abdominal pain and constipation. She had severe epigastric pain radiating to the right side, nausea, vomiting, and diarrhea, with no relief from her usual oral Dilaudid. Labs showed leukocytosis and mild metabolic abnormalities. Imaging confirmed appropriate GJ tube placement without obstruction. She was treated with IV fluids, pain control using scheduled IV Dilaudid, and initiation of oral naloxone for opioid-induced constipation, which led to a successful bowel movement. She advanced to clear liquids and tolerated tube feeds. A Code Purple occurred when she attempted to take unauthorized pills, leading to sedation with Ativan and Zyprexa. Antibiotics for mild G-tube site erythema were discontinued after reassessment. Her insulin regimen was continued without change. She was discharged home with an aggressive bowel regimen, clear instructions on pain management, and follow-up plans.",
    "problems": [
      "Other constipation",
      "Chronic pancreatitis",
      "Diabetes with neurological manifestations, type I [juvenile type], not stated as uncontrolled",
      "Gastroparesis",
      "Asthma, unspecified type, unspecified",
      "Unspecified delay in development",
      "Borderline personality disorder",
      "Gastrostomy status"
    ]
  }
}
